/* 是否存在需要整改的项（扣分项：非不涉及且得分低于满分）；满分时无需整改，不显示整改通知书相关选项 */
const hasRectifyItems = computed(() => {
  const f = form.value
  if (!f) return false
  for (const cat of f.categoryList) for (const proj of cat.projectList) for (const it of proj.itemList) {
    if (it.isNotApplicable !== '1' && it.itemScore != null && it.itemScore !== '' && Number(it.itemScore) < topScore(it)) return true
  }
  return false
})

if (hasRectifyItems.value) {
  if (!f.isGenerateNotice) { toastError('请选择是否生成整改通知书'); return }
  if (f.isGenerateNotice === '1' && !f.rectifyDeadline) { toastError('请选择整改截止日期'); return }
}

